param([Parameter(Mandatory=$true)][string]$binary,[Parameter(Mandatory=$true)][string]$output)
$ErrorActionPreference='Stop';Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Drawing
$a=[Reflection.Assembly]::LoadFrom($binary);$t=$a.GetType('Awl.Shell');$flags=[Reflection.BindingFlags]'Instance,NonPublic';$static=[Reflection.BindingFlags]'Static,NonPublic';$root=Join-Path $output 'profile';[IO.Directory]::CreateDirectory($root)|Out-Null;Copy-Item -LiteralPath "$env:LOCALAPPDATA\Awl\config.json" -Destination $root;$t.GetField('Root',$static).SetValue($null,$root);$app=[Activator]::CreateInstance($t);if($t.GetField('configPath',$flags).GetValue($app) -ne (Join-Path $root 'config.json')){throw 'Capture test profile isolation failed'};$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown
function Invoke-Awl($name,[object[]]$values=@()){$arguments=[object[]]::new($values.Length);for($i=0;$i -lt $values.Length;$i++){$arguments[$i]=$values[$i].PSObject.BaseObject};$t.GetMethod($name,$flags).Invoke($app,$arguments)}
function Field($name){$t.GetField($name,$flags).GetValue($app)}
function Set-Field($name,$value){$t.GetField($name,$flags).SetValue($app,$value)}
Invoke-Awl 'LoadConfig';$cfg=Field 'cfg';$cfg.GuiScale=1;$cfg.CaptureToolScale=0;$cfg.CaptureRecorderScale=0;$cfg.MenuOpacity=1;$cfg.CaptureHideShell=$false;$cfg.CaptureHideDesktopIcons=$false;$cfg.CaptureHideCursor=$true;$cfg.ComponentColorsCustom=$false;$cfg.TemplateComponentColors.Clear();Invoke-Awl 'ApplyTheme'
Set-Field 'baseColor' ([Windows.Media.ColorConverter]::ConvertFromString('#14181b'));Set-Field 'ink' ([Windows.Media.BrushConverter]::new().ConvertFromString('#eef1f2'));Set-Field 'mutedBrush' ([Windows.Media.BrushConverter]::new().ConvertFromString('#a7afb4'));Set-Field 'accentBrush' ([Windows.Media.BrushConverter]::new().ConvertFromString('#5b9aa0'))
function Pump([double]$seconds){$frame=[Windows.Threading.DispatcherFrame]::new();$clock=[Windows.Threading.DispatcherTimer]::new();$clock.Interval=[TimeSpan]::FromSeconds($seconds);$clock.Add_Tick({$clock.Stop();$frame.Continue=$false}.GetNewClosure());$clock.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function Snapshot($element,$name){$element.UpdateLayout();$element.Dispatcher.Invoke([Action]{},[Windows.Threading.DispatcherPriority]::Render);$visual=if($element -is [Windows.Window]){$element.Content}else{$element};$image=[Windows.Media.Imaging.RenderTargetBitmap]::new([int][Math]::Ceiling($element.ActualWidth),[int][Math]::Ceiling($element.ActualHeight),96,96,[Windows.Media.PixelFormats]::Pbgra32);$image.Render($visual);$encoder=[Windows.Media.Imaging.PngBitmapEncoder]::new();$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($image));$f=[IO.File]::Create((Join-Path $output ($name+'.png')));$encoder.Save($f);$f.Dispose();Write-Output ($name+': '+$element.ActualWidth+'x'+$element.ActualHeight)}
function Buttons($node){if($node -is [Windows.Controls.Button]){Write-Output $node};if($node -is [Windows.Controls.Panel]){foreach($child in $node.Children){Buttons $child}}elseif($node -is [Windows.Controls.Decorator]){Buttons $node.Child}}
Invoke-Awl 'ShowCaptureTool';$window=Field 'captureWindow';Snapshot $window 'idle';if([Math]::Abs($window.Height-54) -gt .1){throw 'Capture bar height incorrect'};$brush=$window.Content.Background;if($brush.Color.A -ne 255){throw '100% opacity is not opaque'}
Invoke-Awl 'DrawCaptureStart' @($true);Snapshot $window 'settings';Invoke-Awl 'DrawCaptureStart' @($false)
$cfg.GuiScale=.5;Invoke-Awl 'DrawCaptureStart' @($false);Snapshot $window 'idle-half';if([Math]::Abs($window.Height-27) -gt .1){throw 'Capture scale incorrect'};$cfg.GuiScale=1;Invoke-Awl 'DrawCaptureStart' @($false)
$cover=[Windows.Window]::new();$cover.Title='Awl capture test surface';$cover.WindowStyle=[Windows.WindowStyle]::None;$cover.ResizeMode=[Windows.ResizeMode]::NoResize;$cover.Left=60;$cover.Top=240;$cover.Width=320;$cover.Height=180;$cover.Background=[Windows.Media.Brushes]::Teal;$cover.Topmost=$true;$cover.Show();$cover.UpdateLayout();$point=$cover.PointToScreen([Windows.Point]::new(0,0));$rect=[Drawing.Rectangle]::new([int]$point.X,[int]$point.Y,320,180)
Invoke-Awl 'ShowRecordingBar' @($rect);$bar=Field 'captureRecordWindow';Snapshot $bar 'record-ready';$buttons=@(Buttons $bar.Content);$preset=$buttons|Where-Object {$_.ToolTip -eq 'Recording quality preset'};$entries=[Collections.Generic.List[Tuple[string,string,string,Action]]]::new();foreach($name in @('Discord Free','Discord Basic','Discord Nitro','Native · 320×180')){$entries.Add([Tuple[string,string,string,Action]]::new($name.Replace($name,'record'),$name,'320 × 180',[Action]{}))};$popup=Invoke-Awl 'CaptureDropdown' @($preset,$entries,$false,[string]$cfg.CapturePreset);$bar.UpdateLayout();$bar.Dispatcher.Invoke([Action]{},[Windows.Threading.DispatcherPriority]::Render);Snapshot $popup.Child 'presets';$popup.IsOpen=$false
$start=$buttons|Where-Object {$_.ToolTip -eq 'Start recording'};$start.RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Button]::ClickEvent));Pump 1.6;$bar.Dispatcher.Invoke([Action]{},[Windows.Threading.DispatcherPriority]::Render);Snapshot $bar 'recording'
$rec=Field 'activeRecorder';if($null -eq $rec){throw 'Recording did not start'}
$time=$bar.Content.Child.Children[0].Children[1];$firstTime=$time.Text;$firstSize=(Field 'captureQualityDetail').Text;$surface=$bar.Content
Invoke-Awl 'SetCaptureBarContent' @($bar,$bar.Content.Child,'Recording controls');Invoke-Awl 'SetCaptureBarContent' @($bar,$bar.Content.Child,'Recording controls');if(![Object]::ReferenceEquals($surface,$bar.Content)){throw 'Resize replaced surface'}
Pump 2.2;$secondTime=$time.Text;$secondSize=(Field 'captureQualityDetail').Text;if($firstTime -eq '00:00' -or $secondTime -eq $firstTime){throw 'Visible timer did not advance'};if($firstSize -eq $secondSize){throw 'Visible size did not advance'};Write-Output ('Live display: '+$firstTime+' / '+$firstSize+' -> '+$secondTime+' / '+$secondSize);Snapshot $bar 'live-counters'
$pause=$buttons|Where-Object {$_.ToolTip -eq 'Pause recording'};$pause.RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Button]::ClickEvent));if(!$rec.Paused -or $pause.ToolTip -ne 'Resume recording'){throw 'Pause state not updated'};$pausedTime=$time.Text;$pausedDuration=$rec.Duration.TotalSeconds;Pump .8;if($time.Text -ne $pausedTime -or [Math]::Abs($rec.Duration.TotalSeconds-$pausedDuration) -gt .05){throw 'Paused timer advanced'};Snapshot $bar 'paused';$pause.RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Button]::ClickEvent));if($rec.Paused){throw 'Resume failed'};Pump 1.2;if($time.Text -eq $pausedTime){throw 'Visible timer did not resume'}
$escape=[Windows.Input.KeyEventArgs]::new([Windows.Input.Keyboard]::PrimaryDevice,[Windows.PresentationSource]::FromVisual($bar),0,[Windows.Input.Key]::Escape);$escape.RoutedEvent=[Windows.Input.Keyboard]::PreviewKeyDownEvent;$bar.RaiseEvent($escape);if((Field 'activeRecorder') -ne $rec){throw 'Escape canceled active recording'}
Start-Sleep -Seconds 1;$rec.GetType().GetMethod('Stop').Invoke($rec,@());$timer=Field 'captureUiTimer';$timer.Stop();Set-Field 'activeRecorder' $null;$bar.Close();$cover.Close();$window.Close()
$result=$t.GetMethod('CaptureSelfTest').Invoke($app,@());Write-Output $result;if($result -like 'FAILED:*'){throw $result};$result=$t.GetMethod('CaptureTimingSelfTest').Invoke($app,@());Write-Output $result;if($result -like 'FAILED:*'){throw $result}
Write-Output 'Bar layout, scaling, full opacity, recording start, pause/resume and Escape checks passed'